INSERT INTO onto_version (version, released, bundle) VALUES ('1.0.0', '2026-10-25', '{"meta": {"name": "DiligenceIQ Databook Ontology", "version": "1.0.0", "released": "2026-10-25", "namespaces": {"fin": "Financial statements (P&L, BS, CF, equity, fixed assets)", "drv": "Derived metrics computed in code", "qoe": "Quality of earnings", "debt": "Debt and debt-like", "lease": "Leases and rent", "deal": "Deal terms and valuation", "kpi": "Commercial KPIs (sector-neutral)", "ops": "Operating and people metrics", "mkt": "Market sizing and competition", "svy": "Survey and interview measures", "sec": "Sector packs (sec.rc, sec.fr, sec.hc, sec.pay)"}, "conventions": ["One fact = one concept, one value, one period, one basis, one set of dimension members, one unit, one source location.", "Expenses, costs and cash outflows are stored as positive magnitudes; calculation weights carry the sign. Concepts flagged signed=true carry their own sign.", "Revenue, cost and KPI splits are dimension members on the parent concept, never new concepts (revenue[service_line=<member>]).", "Derived metrics (drv.*) are computed by the calculation engine from stored facts; an extracted ratio is kept only as a comparative.", "EBITDA always carries view = REPORTED | MANAGEMENT | ADVISER | DILIGENCE | PRO_FORMA; bridges between views are QoE adjustment records.", "Nothing in the ontology names a company, file, sheet or deal figure. Deal-specific content lives in facts and records only.", "Sector packs add concepts under sec.*; they never change core concepts, and may add vocabulary to core concepts (synonym extensions). A deal activates packs through its deal profile.", "Lines are stored; subtotals and ratios are derived by the calculation linkbase. A source''s own subtotals, ratios and annual columns are kept as COMPARATIVE facts and tested (R-SRC-01/02/03).", "Classification (current or non-current; operating, investing or financing) follows the source''s open section; ontology parent links are the default when no section is open.", "Period type comes from the months a figure covers, never from a column header; FY, YTD and LTM are derived from months using the deal''s fiscal year end.", "A company''s own EBITDA line is view=MANAGEMENT; REPORTED EBITDA is computed from the deal''s EBITDA policy."]}, "period_types": [{"id": "FY", "label": "Fiscal year", "nature": "duration", "months": 12, "rule": "Sum of 12 fiscal months, or a source that states a full year."}, {"id": "FH", "label": "Fiscal half-year", "nature": "duration", "months": 6, "rule": "Sum of 6 months."}, {"id": "FQ", "label": "Fiscal quarter", "nature": "duration", "months": 3, "rule": "Sum of 3 months."}, {"id": "FM", "label": "Fiscal month", "nature": "duration", "months": 1, "rule": "One calendar or fiscal month."}, {"id": "YTD", "label": "Year to date", "nature": "duration", "months": "1-11", "rule": "Sum of months from fiscal year start to period_end; months_covered < 12."}, {"id": "LTM", "label": "Last twelve months", "nature": "duration", "months": 12, "rule": "Sum of the last 12 FM facts ending at period_end. Derived in code."}, {"id": "AS_AT", "label": "As at a date", "nature": "instant", "months": 0, "rule": "Balance at a month-end (or stated) date."}, {"id": "POINT", "label": "Point attribute (no period)", "nature": "none", "months": 0, "rule": "Terms and parameters such as a rate or a price."}], "period_policies": {"ALL_FY_ACTUAL": "Every fiscal year in the history window (default: last 3 complete FYs, configurable).", "YTD_CURRENT": "Year to date to the latest actual month.", "YTD_PRIOR": "Same months of the prior fiscal year.", "LTM_LATEST": "LTM to the latest actual month.", "MONTHLY_LTM": "The 12 fiscal months ending at the latest actual month.", "AS_AT_FY_ENDS": "Each fiscal year-end in the window plus the opening balance before the first year.", "AS_AT_LATEST": "The latest month-end balance sheet.", "PLAN_YEARS": "Every forward plan year in the latest management plan.", "POINT": "No period; terms and parameters."}, "bases": [{"id": "ACTUAL", "label": "Actual"}, {"id": "BUDGET", "label": "Budget"}, {"id": "FORECAST", "label": "Forecast / plan / projection"}, {"id": "MGMT_CASE", "label": "Management case (deal model)"}, {"id": "PRO_FORMA", "label": "Pro forma (as if)"}, {"id": "ADJUSTED", "label": "Adjusted (QoE)"}, {"id": "MARKET_ESTIMATE", "label": "Market estimate (third-party or management sizing)"}, {"id": "SURVEY", "label": "Primary research result"}], "unit_types": [{"id": "CURRENCY", "scale_applies": true, "store": "value in currency units after scale; currency code required"}, {"id": "CURRENCY_PER_UNIT", "scale_applies": false, "store": "currency per stated unit (per month, per gallon, per home); unit_label required"}, {"id": "COUNT", "scale_applies": false, "store": "integer count; unit_label states the noun (accounts, locations, patients)"}, {"id": "PERCENT", "scale_applies": false, "store": "fraction (0.304 = 30.4%)"}, {"id": "RATIO", "scale_applies": false, "store": "plain ratio; basis points stored as fraction"}, {"id": "MULTIPLE", "scale_applies": false, "store": "times (x)"}, {"id": "DAYS", "scale_applies": false, "store": "days"}, {"id": "YEARS", "scale_applies": false, "store": "years"}, {"id": "VOLUME", "scale_applies": true, "store": "unit_label required (gallons, litres)"}, {"id": "MASS", "scale_applies": true, "store": "unit_label required (tons, tonnes)"}, {"id": "SCORE", "scale_applies": false, "store": "score on a stated scale (NPS -100..100, Likert 1..5)"}, {"id": "OTHER", "scale_applies": false, "store": "unit_label required"}], "dimensions": [{"id": "view", "kind": "closed", "members": ["REPORTED", "MANAGEMENT", "ADVISER", "DILIGENCE", "PRO_FORMA", "CIM"], "used_by": "fin.pl.ebitda, qoe.*"}, {"id": "scenario", "kind": "closed", "members": ["BASE", "DOWNSIDE", "UPSIDE", "SELLER_CASE", "MOMENTUM", "PLAN"], "used_by": "sensitivities, plan, market"}, {"id": "segment", "kind": "open", "note": "Customer or business segment as the company reports it; members registered per deal."}, {"id": "service_line", "kind": "open", "note": "Product or service line; members registered per deal."}, {"id": "customer_type", "kind": "open"}, {"id": "product", "kind": "open"}, {"id": "channel", "kind": "open"}, {"id": "geography", "kind": "open"}, {"id": "site", "kind": "open", "note": "Site, branch, clinic, store; members from the site register."}, {"id": "legal_entity", "kind": "open"}, {"id": "customer", "kind": "open", "note": "Anonymised IDs allowed."}, {"id": "practitioner", "kind": "open"}, {"id": "cohort", "kind": "open", "note": "Cohort start period (e.g. 2023 or 2023-02)."}, {"id": "tenure", "kind": "open"}, {"id": "top_n", "kind": "closed", "members": [1, 3, 5, 10, 20, 50]}, {"id": "balance_source", "kind": "closed", "members": ["BOOK", "SCHEDULE", "LENDER_STATEMENT"], "note": "Where a facility balance comes from: the ledger (BOOK), the amortisation schedule (SCHEDULE) or the lender. R-DEBT-01 ties BOOK to the balance sheet; R-DEBT-02 tests SCHEDULE against BOOK."}, {"id": "facility", "kind": "open", "note": "Debt facility ID from the facility register."}, {"id": "lender", "kind": "open"}, {"id": "debt_class", "kind": "closed", "members": ["TERM_LOAN", "VEHICLE_EQUIPMENT_LOAN", "REVOLVER_LINE", "NOTES", "GOVERNMENT_LOAN", "FINANCE_OBLIGATION", "CONVERTIBLE", "SHAREHOLDER_LOAN", "OTHER"]}, {"id": "debt_like_type", "kind": "closed", "members": ["ACCRUED_DIVIDENDS", "DEFERRED_REVENUE", "CAPEX_PAYABLES", "CUSTOMER_DEPOSITS", "TAXES", "DEFERRED_CONSIDERATION", "PROVISIONS", "RELATED_PARTY", "GRANTS_REPAYABLE", "SUPPLIER_REBATES", "OTHER"]}, {"id": "lease", "kind": "open"}, {"id": "asset_class", "kind": "open"}, {"id": "asset_register", "kind": "closed", "members": ["PPE", "ROU", "INTANGIBLE"]}, {"id": "adjustment", "kind": "open", "note": "Adjustment ref (ADJ-01, PF-02) from the adjustment register."}, {"id": "sensitivity", "kind": "open"}, {"id": "wc_line", "kind": "open"}, {"id": "opex_line", "kind": "open"}, {"id": "cost_centre", "kind": "open"}, {"id": "ageing_bucket", "kind": "open"}, {"id": "market_scope", "kind": "closed", "members": ["CURRENT", "EXPANDED"]}, {"id": "source_basis", "kind": "closed", "members": ["MANAGEMENT", "THIRD_PARTY", "DILIGENCE"]}, {"id": "competitor", "kind": "open"}, {"id": "provider", "kind": "open"}, {"id": "criterion", "kind": "open"}, {"id": "survey", "kind": "open"}, {"id": "respondent_segment", "kind": "open"}, {"id": "role", "kind": "open"}, {"id": "function", "kind": "open"}, {"id": "employment_type", "kind": "open"}, {"id": "site_status", "kind": "closed", "members": ["OPERATED", "OWNED", "LEASED", "OPENED", "ACQUIRED", "SOLD", "CLOSED", "PLANNED"]}, {"id": "fuel_type", "kind": "open"}, {"id": "category", "kind": "open"}, {"id": "payer", "kind": "open"}, {"id": "procedure_type", "kind": "open"}, {"id": "vertical", "kind": "open"}, {"id": "partner_type", "kind": "open"}, {"id": "contract", "kind": "open"}, {"id": "maturity_year", "kind": "open"}, {"id": "lease_year", "kind": "open"}, {"id": "price_type", "kind": "closed", "members": ["LIST", "REALISED", "PLAN", "COMPETITOR"]}, {"id": "driver", "kind": "open"}, {"id": "growth_metric", "kind": "open"}, {"id": "series", "kind": "open"}, {"id": "metric", "kind": "open"}, {"id": "year", "kind": "open"}, {"id": "counterparty", "kind": "open"}, {"id": "case", "kind": "open"}, {"id": "line", "kind": "open", "note": "Source sub-line kept under its parent concept when the source is finer than the ontology (e.g. three fleet-cost lines under fin.pl.cos.vehicle_fleet). Members sum to the concept (R-DIM-01)."}], "evidence_tiers": [{"id": "A", "label": "Tier A: audited, signed, system-of-record or executed contract"}, {"id": "B", "label": "Tier B: management accounts, management workbooks and schedules"}, {"id": "C", "label": "Tier C: marketing documents, third-party estimates, web, diligence agents"}], "document_types": [{"id": "FIN_AUDITED_FS", "label": "Audited or reviewed financial statements", "evidence_tier": "A", "default_basis": "ACTUAL", "routes_to_modules": ["financial"], "recognition_hints": ["auditor''s report", "independent auditor", "statement of financial position", "notes to the financial statements"]}, {"id": "FIN_REVIEWED_FS", "label": "Reviewed / compiled financial statements", "evidence_tier": "A", "default_basis": "ACTUAL", "routes_to_modules": ["financial"], "recognition_hints": ["review report", "compilation report"]}, {"id": "FIN_MGMT_ACCOUNTS", "label": "Management accounts (monthly P&L, BS, CF exports)", "evidence_tier": "B", "default_basis": "ACTUAL", "routes_to_modules": ["financial"], "recognition_hints": ["profit and loss", "balance sheet", "monthly", "ytd", "accounting system export"]}, {"id": "FIN_TRIAL_BALANCE", "label": "Trial balance", "evidence_tier": "B", "default_basis": "ACTUAL", "routes_to_modules": ["financial"], "recognition_hints": ["trial balance", "debit", "credit", "account code"]}, {"id": "FIN_GENERAL_LEDGER", "label": "General ledger / transaction detail", "evidence_tier": "B", "default_basis": "ACTUAL", "routes_to_modules": ["financial"], "recognition_hints": ["journal", "transaction", "gl"]}, {"id": "FIN_TAX_RETURN", "label": "Tax returns", "evidence_tier": "A", "default_basis": "ACTUAL", "routes_to_modules": ["financial"], "recognition_hints": ["tax return", "form 1120", "form 1065"]}, {"id": "FIN_BUDGET", "label": "Budget", "evidence_tier": "B", "default_basis": "BUDGET", "routes_to_modules": ["financial"], "recognition_hints": ["budget"]}, {"id": "FIN_MGMT_MODEL", "label": "Management financial model / projections", "evidence_tier": "B", "default_basis": "FORECAST", "routes_to_modules": ["financial", "commercial"], "recognition_hints": ["projection", "forecast", "scenario model", "plan"]}, {"id": "FIN_INVESTOR_WORKBOOK", "label": "Investor or data book workbook prepared by management or adviser", "evidence_tier": "B", "default_basis": "ACTUAL", "routes_to_modules": ["financial", "commercial"], "recognition_hints": ["investor workbook", "crosswalk", "databook", "kpi"]}, {"id": "FIN_QOE_REPORT", "label": "Third-party quality-of-earnings report", "evidence_tier": "B", "default_basis": "ADJUSTED", "routes_to_modules": ["financial"], "recognition_hints": ["quality of earnings", "ebitda adjustments", "pro forma"]}, {"id": "FIN_FDD_REPORT", "label": "Third-party financial due diligence report", "evidence_tier": "B", "default_basis": "ADJUSTED", "routes_to_modules": ["financial"], "recognition_hints": ["financial due diligence", "normalised ebitda", "net debt"]}, {"id": "FIN_FIXED_ASSET_REGISTER", "label": "Fixed-asset register / depreciation schedule", "evidence_tier": "B", "default_basis": "ACTUAL", "routes_to_modules": ["financial"], "recognition_hints": ["depreciation schedule", "asset register", "accumulated depreciation", "nbv"]}, {"id": "DEBT_LOAN_AGREEMENT", "label": "Loan agreement / credit facility", "evidence_tier": "A", "default_basis": "ACTUAL", "routes_to_modules": ["financial"], "recognition_hints": ["loan agreement", "facility agreement", "promissory note", "borrower", "lender"]}, {"id": "DEBT_LENDER_STATEMENT", "label": "Lender statement", "evidence_tier": "A", "default_basis": "ACTUAL", "routes_to_modules": ["financial"], "recognition_hints": ["statement of account", "payoff"]}, {"id": "DEBT_SCHEDULE", "label": "Debt / loan schedule prepared by the company", "evidence_tier": "B", "default_basis": "ACTUAL", "routes_to_modules": ["financial"], "recognition_hints": ["loan schedule", "amortization", "amortisation", "maturity date", "original amount"]}, {"id": "LEASE_AGREEMENT", "label": "Lease agreement", "evidence_tier": "A", "default_basis": "ACTUAL", "routes_to_modules": ["financial", "legal"], "recognition_hints": ["lease", "landlord", "tenant", "premises", "base rent"]}, {"id": "LEASE_SCHEDULE", "label": "Lease schedule / ASC 842 / IFRS 16 workbook", "evidence_tier": "B", "default_basis": "ACTUAL", "routes_to_modules": ["financial"], "recognition_hints": ["lease schedule", "right of use", "lease liability"]}, {"id": "CAP_TABLE", "label": "Capitalisation table", "evidence_tier": "B", "default_basis": "ACTUAL", "routes_to_modules": ["cap_table"], "recognition_hints": ["cap table", "fully diluted", "preferred", "options"]}, {"id": "SECURITIES_LEDGER", "label": "Securities / equity ledger", "evidence_tier": "B", "default_basis": "ACTUAL", "routes_to_modules": ["cap_table"], "recognition_hints": ["securities ledger", "certificate", "issuance"]}, {"id": "CONTRACT_CUSTOMER", "label": "Customer contract", "evidence_tier": "A", "default_basis": "ACTUAL", "routes_to_modules": ["commercial", "legal"], "recognition_hints": ["agreement", "statement of work", "term", "renewal", "price"]}, {"id": "CONTRACT_SUPPLIER", "label": "Supplier contract", "evidence_tier": "A", "default_basis": "ACTUAL", "routes_to_modules": ["commercial", "legal"], "recognition_hints": ["supply agreement", "purchase agreement"]}, {"id": "CONTRACT_GRANT", "label": "Grant agreement", "evidence_tier": "A", "default_basis": "ACTUAL", "routes_to_modules": ["financial", "legal"], "recognition_hints": ["grant", "award", "matching funds"]}, {"id": "KPI_SYSTEM_EXTRACT", "label": "System extract (billing, CRM, subscription, POS, PMS)", "evidence_tier": "A", "default_basis": "ACTUAL", "routes_to_modules": ["commercial"], "recognition_hints": ["export", "subscription", "invoice", "transactions", "customer id"]}, {"id": "KPI_CUSTOMER_LIST", "label": "Customer list / revenue by customer", "evidence_tier": "B", "default_basis": "ACTUAL", "routes_to_modules": ["commercial"], "recognition_hints": ["customer", "account", "revenue by customer"]}, {"id": "KPI_MGMT_REPORT", "label": "Management KPI report / board pack", "evidence_tier": "B", "default_basis": "ACTUAL", "routes_to_modules": ["commercial", "financial"], "recognition_hints": ["kpi", "dashboard", "board"]}, {"id": "HR_PAYROLL_EXTRACT", "label": "Payroll / HR extract / headcount listing", "evidence_tier": "B", "default_basis": "ACTUAL", "routes_to_modules": ["financial", "commercial"], "recognition_hints": ["payroll", "employee", "fte", "headcount"]}, {"id": "MKT_SIZING_MODEL", "label": "Management market-sizing model", "evidence_tier": "B", "default_basis": "MARKET_ESTIMATE", "routes_to_modules": ["market"], "recognition_hints": ["tam", "sam", "som", "market sizing"]}, {"id": "MKT_THIRD_PARTY_REPORT", "label": "Third-party market report", "evidence_tier": "C", "default_basis": "MARKET_ESTIMATE", "routes_to_modules": ["market"], "recognition_hints": ["market report", "industry report", "cagr", "forecast period"]}, {"id": "MKT_PUBLIC_DATA", "label": "Public statistics (census, regulator, trade body)", "evidence_tier": "B", "default_basis": "MARKET_ESTIMATE", "routes_to_modules": ["market"], "recognition_hints": ["census", "bureau", "statistics", "regulator"]}, {"id": "MKT_SURVEY_DATA", "label": "Primary survey data", "evidence_tier": "A", "default_basis": "SURVEY", "routes_to_modules": ["market"], "recognition_hints": ["respondent", "survey", "question", "n="]}, {"id": "MKT_INTERVIEW_NOTES", "label": "Interview notes / transcripts", "evidence_tier": "B", "default_basis": "SURVEY", "routes_to_modules": ["market"], "recognition_hints": ["interview", "transcript", "expert call"]}, {"id": "MKT_COMPETITOR_INFO", "label": "Competitor information (filings, price lists, sites)", "evidence_tier": "C", "default_basis": "MARKET_ESTIMATE", "routes_to_modules": ["market"], "recognition_hints": ["competitor", "price list"]}, {"id": "MKT_WEB_RESEARCH", "label": "Web research", "evidence_tier": "C", "default_basis": "MARKET_ESTIMATE", "routes_to_modules": ["market"], "recognition_hints": ["website", "http"]}, {"id": "CIM", "label": "Confidential information memorandum", "evidence_tier": "C", "default_basis": "ACTUAL", "routes_to_modules": ["commercial", "financial"], "recognition_hints": ["confidential information memorandum", "cim", "investment highlights"]}, {"id": "TEASER", "label": "Teaser", "evidence_tier": "C", "default_basis": "ACTUAL", "routes_to_modules": ["commercial"], "recognition_hints": ["teaser"]}, {"id": "PROCESS_LETTER", "label": "Process letter", "evidence_tier": "B", "default_basis": "ACTUAL", "routes_to_modules": ["deal"], "recognition_hints": ["process letter", "bid", "indicative offer"]}, {"id": "DEAL_TERM_SHEET", "label": "Term sheet / LOI", "evidence_tier": "A", "default_basis": "ACTUAL", "routes_to_modules": ["deal"], "recognition_hints": ["term sheet", "letter of intent"]}, {"id": "DEAL_SPA", "label": "Sale and purchase agreement / investment agreement", "evidence_tier": "A", "default_basis": "ACTUAL", "routes_to_modules": ["deal", "legal"], "recognition_hints": ["share purchase agreement", "spa", "purchase price"]}, {"id": "DEAL_MODEL", "label": "Buyer or sponsor deal model", "evidence_tier": "B", "default_basis": "MGMT_CASE", "routes_to_modules": ["deal"], "recognition_hints": ["irr", "exit", "returns", "hold"]}, {"id": "APPRAISAL", "label": "Valuation / appraisal report", "evidence_tier": "B", "default_basis": "MARKET_ESTIMATE", "routes_to_modules": ["deal", "financial"], "recognition_hints": ["appraisal", "market value", "cap rate"]}, {"id": "LEGAL_DD_REPORT", "label": "Legal due diligence report", "evidence_tier": "B", "default_basis": "ACTUAL", "routes_to_modules": ["legal"], "recognition_hints": ["legal due diligence"]}, {"id": "ESG_REPORT", "label": "ESG / impact report", "evidence_tier": "B", "default_basis": "ACTUAL", "routes_to_modules": ["esg"], "recognition_hints": ["impact", "emissions", "diversion", "ghg"]}, {"id": "MARKETING_MATERIAL", "label": "Sales proposals, brochures, decks", "evidence_tier": "C", "default_basis": "ACTUAL", "routes_to_modules": ["commercial"], "recognition_hints": ["proposal", "brochure"]}, {"id": "CORPORATE_DOCS", "label": "Corporate and governance documents", "evidence_tier": "A", "default_basis": "ACTUAL", "routes_to_modules": ["legal"], "recognition_hints": ["articles", "bo