ting.other", "weight": 1}], "residual": null, "when": "all_children_present_or_residual", "abs_tol": 1.0, "rel_tol": 0.001, "severity": "block"}, {"id": "SUM:fin.pl.opex", "type": "summation", "parent": "fin.pl.opex", "children": [{"concept": "fin.pl.opex.labour", "weight": 1}, {"concept": "fin.pl.opex.owner_remuneration", "weight": 1}, {"concept": "fin.pl.opex.rent", "weight": 1}, {"concept": "fin.pl.opex.professional_fees", "weight": 1}, {"concept": "fin.pl.opex.insurance", "weight": 1}, {"concept": "fin.pl.opex.marketing", "weight": 1}, {"concept": "fin.pl.opex.it_communication", "weight": 1}, {"concept": "fin.pl.opex.office_admin", "weight": 1}, {"concept": "fin.pl.opex.travel", "weight": 1}, {"concept": "fin.pl.opex.taxes_licences", "weight": 1}, {"concept": "fin.pl.opex.bank_charges", "weight": 1}, {"concept": "fin.pl.opex.bad_debt", "weight": 1}, {"concept": "fin.pl.opex.repairs_maintenance", "weight": 1}, {"concept": "fin.pl.opex.utilities", "weight": 1}, {"concept": "fin.pl.opex.pre_opening", "weight": 1}, {"concept": "fin.pl.opex.donations", "weight": 1}, {"concept": "fin.pl.opex.other", "weight": 1}, {"concept": "fin.pl.opex.unclassified", "weight": 1}], "residual": "fin.pl.opex.unclassified", "when": "all_children_present_or_residual", "abs_tol": 1.0, "rel_tol": 0.001, "severity": "block"}], "calculations": [{"id": "CALC-00", "target": "*", "expr": "ROLLUP(*)", "period_types": ["FM", "AS_AT"], "note": "Every concept whose stored lines all carry split-dimension members gets an undimensioned total."}, {"id": "CALC-PL-01", "target": "fin.pl.cost_of_sales", "expr": "CHILDREN(fin.pl.cost_of_sales)", "period_types": ["FM"], "note": ""}, {"id": "CALC-PL-02", "target": "fin.pl.opex", "expr": "CHILDREN(fin.pl.opex)", "period_types": ["FM"], "note": ""}, {"id": "CALC-PL-03", "target": "fin.pl.da", "expr": "CHILDREN(fin.pl.da)", "period_types": ["FM"], "note": ""}, {"id": "CALC-PL-04", "target": "fin.pl.non_operating", "expr": "CHILDREN(fin.pl.non_operating)", "period_types": ["FM"], "note": ""}, {"id": "CALC-PL-05", "target": "fin.pl.gross_profit", "expr": "fin.pl.revenue - fin.pl.cost_of_sales", "period_types": ["FM"], "note": ""}, {"id": "CALC-PL-06", "target": "fin.pl.opex_incl_da", "expr": "fin.pl.opex + fin.pl.da?", "period_types": ["FM"], "note": ""}, {"id": "CALC-PL-07", "target": "fin.pl.operating_income", "expr": "fin.pl.gross_profit - fin.pl.opex - fin.pl.da? + policy:include_other_operating_income fin.pl.other_operating_income?", "period_types": ["FM"], "note": ""}, {"id": "CALC-PL-08", "target": "fin.pl.ebitda[view=REPORTED]", "expr": "fin.pl.operating_income + fin.pl.da?", "period_types": ["FM"], "note": "Reported EBITDA is always computed from the policy; a company''s own EBITDA line is stored as view=MANAGEMENT."}, {"id": "CALC-PL-09", "target": "fin.pl.profit_before_tax", "expr": "fin.pl.operating_income + fin.pl.non_operating?", "period_types": ["FM"], "note": ""}, {"id": "CALC-PL-10", "target": "fin.pl.net_income", "expr": "fin.pl.profit_before_tax - fin.pl.income_tax?", "period_types": ["FM"], "note": ""}, {"id": "CALC-BS-01", "target": "fin.bs.current_assets", "expr": "CLASSIFIED(CURRENT_ASSET)", "period_types": ["AS_AT"], "note": ""}, {"id": "CALC-BS-02", "target": "fin.bs.non_current_assets", "expr": "CLASSIFIED(NON_CURRENT_ASSET)", "period_types": ["AS_AT"], "note": ""}, {"id": "CALC-BS-03", "target": "fin.bs.current_liabilities", "expr": "CLASSIFIED(CURRENT_LIABILITY)", "period_types": ["AS_AT"], "note": ""}, {"id": "CALC-BS-04", "target": "fin.bs.non_current_liabilities", "expr": "CLASSIFIED(NON_CURRENT_LIABILITY)", "period_types": ["AS_AT"], "note": ""}, {"id": "CALC-BS-05", "target": "fin.bs.equity", "expr": "CLASSIFIED(EQUITY)", "period_types": ["AS_AT"], "note": ""}, {"id": "CALC-BS-06", "target": "fin.bs.ppe_net", "expr": "fin.bs.ppe_gross - fin.bs.accumulated_depreciation", "period_types": ["AS_AT"], "note": ""}, {"id": "CALC-BS-07", "target": "fin.bs.total_assets", "expr": "fin.bs.current_assets? + fin.bs.non_current_assets?", "period_types": ["AS_AT"], "note": ""}, {"id": "CALC-BS-08", "target": "fin.bs.total_liabilities", "expr": "fin.bs.current_liabilities? + fin.bs.non_current_liabilities?", "period_types": ["AS_AT"], "note": ""}, {"id": "CALC-BS-09", "target": "fin.bs.total_liabilities_and_equity", "expr": "fin.bs.total_liabilities + fin.bs.equity", "period_types": ["AS_AT"], "note": ""}, {"id": "CALC-BS-10", "target": "fin.bs.net_current_assets", "expr": "fin.bs.current_assets - fin.bs.current_liabilities", "period_types": ["AS_AT"], "note": ""}, {"id": "CALC-BS-11", "target": "fin.bs.total_assets_less_current_liabilities", "expr": "fin.bs.total_assets - fin.bs.current_liabilities", "period_types": ["AS_AT"], "note": ""}, {"id": "CALC-CF-01", "target": "fin.cf.operating", "expr": "CLASSIFIED(OPERATING)", "period_types": ["FM"], "note": ""}, {"id": "CALC-CF-02", "target": "fin.cf.investing", "expr": "CLASSIFIED(INVESTING)", "period_types": ["FM"], "note": ""}, {"id": "CALC-CF-03", "target": "fin.cf.financing", "expr": "CLASSIFIED(FINANCING)", "period_types": ["FM"], "note": ""}, {"id": "CALC-CF-04", "target": "fin.cf.net_change_in_cash", "expr": "fin.cf.operating? + fin.cf.investing? + fin.cf.financing?", "period_types": ["FM"], "note": ""}, {"id": "CALC-CF-05", "target": "fin.cf.closing_cash", "expr": "fin.cf.opening_cash + fin.cf.net_change_in_cash", "period_types": ["FM"], "note": ""}, {"id": "CALC-DRV-01", "target": "drv.gross_margin_pct", "expr": "fin.pl.gross_profit / fin.pl.revenue", "period_types": ["FM", "FY", "YTD", "LTM"], "note": "Ratios are recomputed at every period from the period''s own sums; they are never summed or averaged."}, {"id": "CALC-DRV-02", "target": "drv.ebitda_margin_pct[view=*]", "expr": "fin.pl.ebitda[view=*] / fin.pl.revenue", "period_types": ["FM", "FY", "YTD", "LTM"], "note": ""}], "rules": [{"id": "R-PL-01", "type": "identity", "description": "Revenue equals gross revenue less discounts (when both are present).", "severity": "block", "lhs": "fin.pl.revenue", "rhs": "fin.pl.revenue_gross - fin.pl.sales_discounts", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-PL-02", "type": "identity", "description": "Gross profit equals revenue less cost of sales.", "severity": "block", "lhs": "fin.pl.gross_profit", "rhs": "fin.pl.revenue - fin.pl.cost_of_sales", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-PL-03", "type": "identity", "description": "Operating expenses including D&A equal opex plus D&A (when presented).", "severity": "block", "lhs": "fin.pl.opex_incl_da", "rhs": "fin.pl.opex + fin.pl.da", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-PL-04", "type": "identity", "description": "Reported EBITDA equals gross profit less opex plus other operating income (policy: include_other_operating_income).", "severity": "block", "lhs": "fin.pl.ebitda[view=REPORTED]", "rhs": "fin.pl.gross_profit - fin.pl.opex + fin.pl.other_operating_income", "when": "policy:ebitda_from_operations", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-PL-05", "type": "identity", "description": "Reported EBITDA equals net income plus tax, less net non-operating items, plus D&A (definitional cross-check).", "severity": "block", "lhs": "fin.pl.ebitda[view=REPORTED]", "rhs": "fin.pl.net_income + fin.pl.income_tax - fin.pl.non_operating + fin.pl.da", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-PL-06", "type": "identity", "description": "Operating income equals reported EBITDA less D&A.", "severity": "block", "lhs": "fin.pl.operating_income", "rhs": "fin.pl.ebitda[view=REPORTED] - fin.pl.da", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-PL-07", "type": "identity", "description": "Profit before tax equals operating income plus net non-operating items.", "severity": "block", "lhs": "fin.pl.profit_before_tax", "rhs": "fin.pl.operating_income + fin.pl.non_operating", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-PL-08", "type": "identity", "description": "Net income equals profit before tax less income tax.", "severity": "block", "lhs": "fin.pl.net_income", "rhs": "fin.pl.profit_before_tax - fin.pl.income_tax", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-PL-09", "type": "identity", "description": "EBITDAR equals EBITDA plus rent for the stated rent basis.", "severity": "block", "lhs": "fin.pl.ebitdar", "rhs": "fin.pl.ebitda + lease.rent_expense_gaap", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-BS-01", "type": "identity", "description": "Total assets equal current plus non-current assets.", "severity": "block", "lhs": "fin.bs.total_assets", "rhs": "fin.bs.current_assets + fin.bs.non_current_assets", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-BS-02", "type": "identity", "description": "Total liabilities equal current plus non-current liabilities.", "severity": "block", "lhs": "fin.bs.total_liabilities", "rhs": "fin.bs.current_liabilities + fin.bs.non_current_liabilities", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-BS-03", "type": "identity", "description": "The balance sheet balances.", "severity": "block", "lhs": "fin.bs.total_assets", "rhs": "fin.bs.total_liabilities + fin.bs.equity", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-BS-04", "type": "identity", "description": "Net PPE equals cost less accumulated depreciation, per asset class.", "severity": "block", "lhs": "fin.bs.ppe_net", "rhs": "fin.bs.ppe_gross - fin.bs.accumulated_depreciation", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-BS-05", "type": "identity", "description": "Total liabilities and equity equal total assets.", "severity": "block", "lhs": "fin.bs.total_liabilities_and_equity", "rhs": "fin.bs.total_assets", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-CF-01", "type": "identity", "description": "Net change in cash equals operating plus investing plus financing cash flow.", "severity": "block", "lhs": "fin.cf.net_change_in_cash", "rhs": "fin.cf.operating + fin.cf.investing + fin.cf.financing", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-CF-02", "type": "identity", "description": "Closing cash equals opening cash plus net change.", "severity": "block", "lhs": "fin.cf.closing_cash", "rhs": "fin.cf.opening_cash + fin.cf.net_change_in_cash", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-CF-03", "type": "cross_statement", "description": "Cash-flow closing cash equals balance-sheet cash at the period end (plus restricted cash if the policy includes it).", "severity": "block", "lhs": "fin.cf.closing_cash", "rhs": "fin.bs.cash", "align": "period_end", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-CF-04", "type": "continuity", "description": "Opening cash of a period equals closing cash of the previous period.", "severity": "block", "concept_open": "fin.cf.opening_cash", "concept_close": "fin.cf.closing_cash", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-CF-05", "type": "cross_statement", "description": "Cash-flow net income equals P&L net income.", "severity": "block", "lhs": "fin.cf.operating.net_income", "rhs": "fin.pl.net_income", "align": "period", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-CF-06", "type": "cross_statement", "description": "Operating profit starting an indirect cash flow equals operating income in the income statement.", "severity": "block", "lhs": "fin.cf.operating.operating_profit", "rhs": "fin.pl.operating_income", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-EQ-01", "type": "roll_forward", "description": "Equity roll-forward closes and ties to the balance sheet.", "severity": "block", "opening": "fin.eq.opening", "flows": ["+fin.eq.net_income", "+fin.eq.contributions", "-fin.eq.distributions", "+fin.eq.other_movements"], "closing": "fin.eq.closing", "ties_to": "fin.bs.equity", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-DIV-01", "type": "roll_forward", "description": "Dividends payable roll-forward closes and ties to the balance sheet.", "severity": "block", "opening": "fin.divpay.opening", "flows": ["+fin.divpay.accrued", "-fin.divpay.paid"], "closing": "fin.divpay.closing", "ties_to": "fin.bs.dividends_payable", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-FA-01", "type": "roll_forward", "description": "Fixed-asset roll-forward closes and ties to net PPE (per asset register).", "severity": "block", "opening": "fin.fa.opening_nbv", "flows": ["+fin.fa.additions", "-fin.fa.disposals", "-fin.fa.depreciation", "+fin.fa.other"], "closing": "fin.fa.closing_nbv", "ties_to": "fin.bs.ppe_net", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-DEBT-01", "type": "aggregate_tie", "description": "Facility balances at a date sum to balance-sheet borrowings at the same date.", "severity": "warn", "lhs_sum": "debt.balance[balance_source=BOOK]", "group_by": "facility", "rhs": "fin.bs.borrowings_current + fin.bs.borrowings_non_current", "align": "period_end", "abs_tol": 1.0, "rel_tol": 0.01}, {"id": "R-DEBT-02", "type": "record_compare", "description": "Per facility, the amortisation-schedule balance equals the ledger balance at the same date. A schedule balance held for a formula error means the facility cannot be verified.", "severity": "warn", "lhs": "debt.balance[balance_source=SCHEDULE]", "rhs": "debt.balance[balance_source=BOOK]", "group_by": "facility", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-QOE-01", "type": "bridge", "description": "Each EBITDA view equals the view it starts from plus the adjustments into it.", "severity": "block", "concept": "fin.pl.ebitda", "adjustment": "qoe.adjustment_amount", "views": ["REPORTED", "MANAGEMENT", "ADVISER", "DILIGENCE", "PRO_FORMA"], "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-QOE-02", "type": "cross_statement", "description": "Reported EBITDA in the QoE bridge equals reported EBITDA in the income statement.", "severity": "block", "lhs": "fin.pl.ebitda[view=REPORTED]", "rhs": "fin.pl.ebitda[view=REPORTED]", "align": "source_schedule", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-DIM-01", "type": "dimension_rollup", "description": "Members of a complete dimension sum to the undimensioned total (revenue by service line, segment, site).", "severity": "warn", "concepts": ["fin.pl.revenue", "fin.pl.cost_of_sales", "fin.pl.gross_profit", "kpi.customers_active", "kpi.arr"], "dims": ["service_line", "segment", "site", "customer_type"], "abs_tol": 1.0, "rel_tol": 0.005}, {"id": "R-PER-01", "type": "period_sum", "description": "Fiscal-year, quarter and YTD flows equal the sum of their months.", "severity": "block", "concepts": "all duration concepts with aggregation=sum", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-PER-02", "type": "period_label", "description": "A duration fact with months_covered < 12 can never carry period_type FY.", "severity": "block"}, {"id": "R-PER-03", "type": "period_label", "description": "Instant facts are dated at a period end (month-end unless the source states a date).", "severity": "warn"}, {"id": "R-PER-04", "type": "basis_window", "description": "ACTUAL facts end on or before the latest actual month; plan-basis facts may not sit in history views.", "severity": "block"}, {"id": "R-SRC-01", "type": "source_subtotal", "description": "A source subtotal written as a SUM over a row range equals the sum of the extracted lines in that range, and every line in the range is mapped (nothing dropped).", "severity": "block", "applies_to": "row_kind=SUM", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-SRC-02", "type": "source_comparative", "description": "Each subtotal or ratio derived in code equals the source''s own figure for the same concept, period and view. A difference is explained by composition (the source range holds concepts outside the canonical subtotal) or flagged.", "severity": "warn", "applies_to": "status=COMPARATIVE and reason_code in (SOURCE_SUBTOTAL, COMPUTED_IN_CODE)", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-SRC-03", "type": "annual_column", "description": "A source annual column equals the FY or YTD derived from the months it covers. Its period type comes from the months covered, never from the column header.", "severity": "warn", "applies_to": "row_kind=ANNUAL_COLUMN", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-SUM-ALL", "type": "summation", "description": "Every subtotal equals the weighted sum of its child concepts when all children (or an unclassified residual) are present.", "severity": "block", "source": "concept.parent links", "abs_tol": 1.0, "rel_tol": 0.001}, {"id": "R-KPI-01", "type": "identity", "description": "ARR equals MRR times 12 at the same date.", "severity": "warn", "lhs": "kpi.arr", "rhs": "12*kpi.mrr", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.005}, {"id": "R-KPI-02", "type": "identity", "description": "Logo churn equals one minus logo retention.", "severity": "warn", "lhs": "kpi.logo_churn_pct", "rhs": "1 - kpi.logo_retention_pct", "when": "all_present", "abs_tol": 0.0005, "rel_tol": 0.0}, {"id": "R-KPI-03", "type": "inequality", "description": "Gross revenue retention never exceeds net revenue retention or 100%.", "severity": "warn", "expr": ["kpi.grr_pct <= kpi.nrr_pct", "kpi.grr_pct <= 1"]}, {"id": "R-KPI-04", "type": "inequality", "description": "Top-N concentration is between 0 and 100% and rises with N.", "severity": "warn", "expr": ["0 <= kpi.concentration_top_n_pct <= 1", "monotone_increasing(kpi.concentration_top_n_pct, top_n)"]}, {"id": "R-KPI-05", "type": "roll_forward", "description": "Customer count rolls forward with new and churned customers (allowing reactivations as a stated residual).", "severity": "warn", "opening": "kpi.customers_active@t-1", "flows": ["+kpi.customers_new", "-kpi.customers_churned"], "closing": "kpi.customers_active@t", "abs_tol": 0, "rel_tol": 0.02}, {"id": "R-MKT-01", "type": "inequality", "description": "TAM is at least SAM, and SAM is at least SOM, for the same scope, segment, geography and year.", "severity": "block", "expr": ["mkt.tam >= mkt.sam", "mkt.sam >= mkt.som"]}, {"id": "R-MKT-02", "typ