": "BOTH", "completeness_weight": 1, "required_periods": ["POINT"], "required_concepts": [], "record_classes": ["data_gap"], "purpose": "What the report could not establish and why.", "all_concepts": []}], "reason_codes": [{"code": "EQUAL_AUTHORITY_CONFLICT", "meaning": "Two sources of equal authority disagree beyond tolerance"}, {"code": "VALIDATION_FAILED", "meaning": "A calculation or identity rule failed; rule id in reason_detail"}, {"code": "NO_PERIOD", "meaning": "Period could not be determined"}, {"code": "PERIOD_CONFLICT", "meaning": "Label period and header period disagree"}, {"code": "NO_UNIT", "meaning": "Unit or scale could not be determined"}, {"code": "IMPLAUSIBLE_VALUE", "meaning": "Plausibility rule failed"}, {"code": "PARENT_UNKNOWN", "meaning": "Line could not be placed under any parent node"}, {"code": "OUT_OF_SCOPE", "meaning": "Document type routed to another module"}, {"code": "SUPERSEDED_VERSION", "meaning": "A newer version of the document exists"}, {"code": "NOT_IN_DATA_ROOM", "meaning": "Document is not part of the deal''s data room"}, {"code": "FORMULA_ERROR", "meaning": "Source cell holds a spreadsheet error value (a broken reference or a failed lookup)"}, {"code": "MISSING_VALUE", "meaning": "The source shows text or nothing where a value should be (for example ''needs data'')"}, {"code": "LABEL_VALUE", "meaning": "Value was found inside a label (ID, code, account number)"}, {"code": "DUPLICATE", "meaning": "Merged into an existing fact with the same key"}, {"code": "LOWER_AUTHORITY", "meaning": "Kept as comparative; a higher-authority source was selected"}, {"code": "USER_EXCLUDED", "meaning": "Excluded by a reviewer, reason recorded"}, {"code": "BASIS_MISMATCH", "meaning": "Plan and actual cannot be compared"}, {"code": "SOURCE_SUBTOTAL", "meaning": "Source subtotal kept as a check; the canonical subtotal is derived from lines in code"}, {"code": "COMPUTED_IN_CODE", "meaning": "Ratio or derived metric recomputed by the calculation engine; the source value is kept as a check"}]}'::jsonb) ON CONFLICT DO NOTHING;
