INSERT INTO onto_schedule VALUES ('1.0.0', 'GOV-05', 'Data gaps and exceptions', 'BOTH', 1, ARRAY['POINT']::text[], '{}'::text[], ARRAY['data_gap']::text[], 'What the report could not establish and why.') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-00', 1, '*', 'ROLLUP(*)', ARRAY['FM','AS_AT']::text[], 'Every concept whose stored lines all carry split-dimension members gets an undimensioned total.') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-PL-01', 2, 'fin.pl.cost_of_sales', 'CHILDREN(fin.pl.cost_of_sales)', ARRAY['FM']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-PL-02', 3, 'fin.pl.opex', 'CHILDREN(fin.pl.opex)', ARRAY['FM']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-PL-03', 4, 'fin.pl.da', 'CHILDREN(fin.pl.da)', ARRAY['FM']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-PL-04', 5, 'fin.pl.non_operating', 'CHILDREN(fin.pl.non_operating)', ARRAY['FM']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-PL-05', 6, 'fin.pl.gross_profit', 'fin.pl.revenue - fin.pl.cost_of_sales', ARRAY['FM']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-PL-06', 7, 'fin.pl.opex_incl_da', 'fin.pl.opex + fin.pl.da?', ARRAY['FM']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-PL-07', 8, 'fin.pl.operating_income', 'fin.pl.gross_profit - fin.pl.opex - fin.pl.da? + policy:include_other_operating_income fin.pl.other_operating_income?', ARRAY['FM']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-PL-08', 9, 'fin.pl.ebitda[view=REPORTED]', 'fin.pl.operating_income + fin.pl.da?', ARRAY['FM']::text[], 'Reported EBITDA is always computed from the policy; a company''s own EBITDA line is stored as view=MANAGEMENT.') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-PL-09', 10, 'fin.pl.profit_before_tax', 'fin.pl.operating_income + fin.pl.non_operating?', ARRAY['FM']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-PL-10', 11, 'fin.pl.net_income', 'fin.pl.profit_before_tax - fin.pl.income_tax?', ARRAY['FM']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-BS-01', 12, 'fin.bs.current_assets', 'CLASSIFIED(CURRENT_ASSET)', ARRAY['AS_AT']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-BS-02', 13, 'fin.bs.non_current_assets', 'CLASSIFIED(NON_CURRENT_ASSET)', ARRAY['AS_AT']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-BS-03', 14, 'fin.bs.current_liabilities', 'CLASSIFIED(CURRENT_LIABILITY)', ARRAY['AS_AT']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-BS-04', 15, 'fin.bs.non_current_liabilities', 'CLASSIFIED(NON_CURRENT_LIABILITY)', ARRAY['AS_AT']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-BS-05', 16, 'fin.bs.equity', 'CLASSIFIED(EQUITY)', ARRAY['AS_AT']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-BS-06', 17, 'fin.bs.ppe_net', 'fin.bs.ppe_gross - fin.bs.accumulated_depreciation', ARRAY['AS_AT']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-BS-07', 18, 'fin.bs.total_assets', 'fin.bs.current_assets? + fin.bs.non_current_assets?', ARRAY['AS_AT']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-BS-08', 19, 'fin.bs.total_liabilities', 'fin.bs.current_liabilities? + fin.bs.non_current_liabilities?', ARRAY['AS_AT']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-BS-09', 20, 'fin.bs.total_liabilities_and_equity', 'fin.bs.total_liabilities + fin.bs.equity', ARRAY['AS_AT']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-BS-10', 21, 'fin.bs.net_current_assets', 'fin.bs.current_assets - fin.bs.current_liabilities', ARRAY['AS_AT']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-BS-11', 22, 'fin.bs.total_assets_less_current_liabilities', 'fin.bs.total_assets - fin.bs.current_liabilities', ARRAY['AS_AT']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-CF-01', 23, 'fin.cf.operating', 'CLASSIFIED(OPERATING)', ARRAY['FM']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-CF-02', 24, 'fin.cf.investing', 'CLASSIFIED(INVESTING)', ARRAY['FM']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-CF-03', 25, 'fin.cf.financing', 'CLASSIFIED(FINANCING)', ARRAY['FM']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-CF-04', 26, 'fin.cf.net_change_in_cash', 'fin.cf.operating? + fin.cf.investing? + fin.cf.financing?', ARRAY['FM']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-CF-05', 27, 'fin.cf.closing_cash', 'fin.cf.opening_cash + fin.cf.net_change_in_cash', ARRAY['FM']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-DRV-01', 28, 'drv.gross_margin_pct', 'fin.pl.gross_profit / fin.pl.revenue', ARRAY['FM','FY','YTD','LTM']::text[], 'Ratios are recomputed at every period from the period''s own sums; they are never summed or averaged.') ON CONFLICT DO NOTHING;
INSERT INTO onto_calculation VALUES ('1.0.0', 'CALC-DRV-02', 29, 'drv.ebitda_margin_pct[view=*]', 'fin.pl.ebitda[view=*] / fin.pl.revenue', ARRAY['FM','FY','YTD','LTM']::text[], '') ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-PL-01', 'identity', 'block', 'Revenue equals gross revenue less discounts (when both are present).', '{"id": "R-PL-01", "type": "identity", "description": "Revenue equals gross revenue less discounts (when both are present).", "severity": "block", "lhs": "fin.pl.revenue", "rhs": "fin.pl.revenue_gross - fin.pl.sales_discounts", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-PL-02', 'identity', 'block', 'Gross profit equals revenue less cost of sales.', '{"id": "R-PL-02", "type": "identity", "description": "Gross profit equals revenue less cost of sales.", "severity": "block", "lhs": "fin.pl.gross_profit", "rhs": "fin.pl.revenue - fin.pl.cost_of_sales", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-PL-03', 'identity', 'block', 'Operating expenses including D&A equal opex plus D&A (when presented).', '{"id": "R-PL-03", "type": "identity", "description": "Operating expenses including D&A equal opex plus D&A (when presented).", "severity": "block", "lhs": "fin.pl.opex_incl_da", "rhs": "fin.pl.opex + fin.pl.da", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-PL-04', 'identity', 'block', 'Reported EBITDA equals gross profit less opex plus other operating income (policy: include_other_operating_income).', '{"id": "R-PL-04", "type": "identity", "description": "Reported EBITDA equals gross profit less opex plus other operating income (policy: include_other_operating_income).", "severity": "block", "lhs": "fin.pl.ebitda[view=REPORTED]", "rhs": "fin.pl.gross_profit - fin.pl.opex + fin.pl.other_operating_income", "when": "policy:ebitda_from_operations", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-PL-05', 'identity', 'block', 'Reported EBITDA equals net income plus tax, less net non-operating items, plus D&A (definitional cross-check).', '{"id": "R-PL-05", "type": "identity", "description": "Reported EBITDA equals net income plus tax, less net non-operating items, plus D&A (definitional cross-check).", "severity": "block", "lhs": "fin.pl.ebitda[view=REPORTED]", "rhs": "fin.pl.net_income + fin.pl.income_tax - fin.pl.non_operating + fin.pl.da", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-PL-06', 'identity', 'block', 'Operating income equals reported EBITDA less D&A.', '{"id": "R-PL-06", "type": "identity", "description": "Operating income equals reported EBITDA less D&A.", "severity": "block", "lhs": "fin.pl.operating_income", "rhs": "fin.pl.ebitda[view=REPORTED] - fin.pl.da", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-PL-07', 'identity', 'block', 'Profit before tax equals operating income plus net non-operating items.', '{"id": "R-PL-07", "type": "identity", "description": "Profit before tax equals operating income plus net non-operating items.", "severity": "block", "lhs": "fin.pl.profit_before_tax", "rhs": "fin.pl.operating_income + fin.pl.non_operating", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-PL-08', 'identity', 'block', 'Net income equals profit before tax less income tax.', '{"id": "R-PL-08", "type": "identity", "description": "Net income equals profit before tax less income tax.", "severity": "block", "lhs": "fin.pl.net_income", "rhs": "fin.pl.profit_before_tax - fin.pl.income_tax", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-PL-09', 'identity', 'block', 'EBITDAR equals EBITDA plus rent for the stated rent basis.', '{"id": "R-PL-09", "type": "identity", "description": "EBITDAR equals EBITDA plus rent for the stated rent basis.", "severity": "block", "lhs": "fin.pl.ebitdar", "rhs": "fin.pl.ebitda + lease.rent_expense_gaap", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-BS-01', 'identity', 'block', 'Total assets equal current plus non-current assets.', '{"id": "R-BS-01", "type": "identity", "description": "Total assets equal current plus non-current assets.", "severity": "block", "lhs": "fin.bs.total_assets", "rhs": "fin.bs.current_assets + fin.bs.non_current_assets", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-BS-02', 'identity', 'block', 'Total liabilities equal current plus non-current liabilities.', '{"id": "R-BS-02", "type": "identity", "description": "Total liabilities equal current plus non-current liabilities.", "severity": "block", "lhs": "fin.bs.total_liabilities", "rhs": "fin.bs.current_liabilities + fin.bs.non_current_liabilities", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-BS-03', 'identity', 'block', 'The balance sheet balances.', '{"id": "R-BS-03", "type": "identity", "description": "The balance sheet balances.", "severity": "block", "lhs": "fin.bs.total_assets", "rhs": "fin.bs.total_liabilities + fin.bs.equity", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-BS-04', 'identity', 'block', 'Net PPE equals cost less accumulated depreciation, per asset class.', '{"id": "R-BS-04", "type": "identity", "description": "Net PPE equals cost less accumulated depreciation, per asset class.", "severity": "block", "lhs": "fin.bs.ppe_net", "rhs": "fin.bs.ppe_gross - fin.bs.accumulated_depreciation", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-BS-05', 'identity', 'block', 'Total liabilities and equity equal total assets.', '{"id": "R-BS-05", "type": "identity", "description": "Total liabilities and equity equal total assets.", "severity": "block", "lhs": "fin.bs.total_liabilities_and_equity", "rhs": "fin.bs.total_assets", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-CF-01', 'identity', 'block', 'Net change in cash equals operating plus investing plus financing cash flow.', '{"id": "R-CF-01", "type": "identity", "description": "Net change in cash equals operating plus investing plus financing cash flow.", "severity": "block", "lhs": "fin.cf.net_change_in_cash", "rhs": "fin.cf.operating + fin.cf.investing + fin.cf.financing", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-CF-02', 'identity', 'block', 'Closing cash equals opening cash plus net change.', '{"id": "R-CF-02", "type": "identity", "description": "Closing cash equals opening cash plus net change.", "severity": "block", "lhs": "fin.cf.closing_cash", "rhs": "fin.cf.opening_cash + fin.cf.net_change_in_cash", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-CF-03', 'cross_statement', 'block', 'Cash-flow closing cash equals balance-sheet cash at the period end (plus restricted cash if the policy includes it).', '{"id": "R-CF-03", "type": "cross_statement", "description": "Cash-flow closing cash equals balance-sheet cash at the period end (plus restricted cash if the policy includes it).", "severity": "block", "lhs": "fin.cf.closing_cash", "rhs": "fin.bs.cash", "align": "period_end", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-CF-04', 'continuity', 'block', 'Opening cash of a period equals closing cash of the previous period.', '{"id": "R-CF-04", "type": "continuity", "description": "Opening cash of a period equals closing cash of the previous period.", "severity": "block", "concept_open": "fin.cf.opening_cash", "concept_close": "fin.cf.closing_cash", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-CF-05', 'cross_statement', 'block', 'Cash-flow net income equals P&L net income.', '{"id": "R-CF-05", "type": "cross_statement", "description": "Cash-flow net income equals P&L net income.", "severity": "block", "lhs": "fin.cf.operating.net_income", "rhs": "fin.pl.net_income", "align": "period", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-CF-06', 'cross_statement', 'block', 'Operating profit starting an indirect cash flow equals operating income in the income statement.', '{"id": "R-CF-06", "type": "cross_statement", "description": "Operating profit starting an indirect cash flow equals operating income in the income statement.", "severity": "block", "lhs": "fin.cf.operating.operating_profit", "rhs": "fin.pl.operating_income", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-EQ-01', 'roll_forward', 'block', 'Equity roll-forward closes and ties to the balance sheet.', '{"id": "R-EQ-01", "type": "roll_forward", "description": "Equity roll-forward closes and ties to the balance sheet.", "severity": "block", "opening": "fin.eq.opening", "flows": ["+fin.eq.net_income", "+fin.eq.contributions", "-fin.eq.distributions", "+fin.eq.other_movements"], "closing": "fin.eq.closing", "ties_to": "fin.bs.equity", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-DIV-01', 'roll_forward', 'block', 'Dividends payable roll-forward closes and ties to the balance sheet.', '{"id": "R-DIV-01", "type": "roll_forward", "description": "Dividends payable roll-forward closes and ties to the balance sheet.", "severity": "block", "opening": "fin.divpay.opening", "flows": ["+fin.divpay.accrued", "-fin.divpay.paid"], "closing": "fin.divpay.closing", "ties_to": "fin.bs.dividends_payable", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-FA-01', 'roll_forward', 'block', 'Fixed-asset roll-forward closes and ties to net PPE (per asset register).', '{"id": "R-FA-01", "type": "roll_forward", "description": "Fixed-asset roll-forward closes and ties to net PPE (per asset register).", "severity": "block", "opening": "fin.fa.opening_nbv", "flows": ["+fin.fa.additions", "-fin.fa.disposals", "-fin.fa.depreciation", "+fin.fa.other"], "closing": "fin.fa.closing_nbv", "ties_to": "fin.bs.ppe_net", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-DEBT-01', 'aggregate_tie', 'warn', 'Facility balances at a date sum to balance-sheet borrowings at the same date.', '{"id": "R-DEBT-01", "type": "aggregate_tie", "description": "Facility balances at a date sum to balance-sheet borrowings at the same date.", "severity": "warn", "lhs_sum": "debt.balance[balance_source=BOOK]", "group_by": "facility", "rhs": "fin.bs.borrowings_current + fin.bs.borrowings_non_current", "align": "period_end", "abs_tol": 1.0, "rel_tol": 0.01}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-DEBT-02', 'record_compare', 'warn', 'Per facility, the amortisation-schedule balance equals the ledger balance at the same date. A schedule balance held for a formula error means the facility cannot be verified.', '{"id": "R-DEBT-02", "type": "record_compare", "description": "Per facility, the amortisation-schedule balance equals the ledger balance at the same date. A schedule balance held for a formula error means the facility cannot be verified.", "severity": "warn", "lhs": "debt.balance[balance_source=SCHEDULE]", "rhs": "debt.balance[balance_source=BOOK]", "group_by": "facility", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-QOE-01', 'bridge', 'block', 'Each EBITDA view equals the view it starts from plus the adjustments into it.', '{"id": "R-QOE-01", "type": "bridge", "description": "Each EBITDA view equals the view it starts from plus the adjustments into it.", "severity": "block", "concept": "fin.pl.ebitda", "adjustment": "qoe.adjustment_amount", "views": ["REPORTED", "MANAGEMENT", "ADVISER", "DILIGENCE", "PRO_FORMA"], "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-QOE-02', 'cross_statement', 'block', 'Reported EBITDA in the QoE bridge equals reported EBITDA in the income statement.', '{"id": "R-QOE-02", "type": "cross_statement", "description": "Reported EBITDA in the QoE bridge equals reported EBITDA in the income statement.", "severity": "block", "lhs": "fin.pl.ebitda[view=REPORTED]", "rhs": "fin.pl.ebitda[view=REPORTED]", "align": "source_schedule", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-DIM-01', 'dimension_rollup', 'warn', 'Members of a complete dimension sum to the undimensioned total (revenue by service line, segment, site).', '{"id": "R-DIM-01", "type": "dimension_rollup", "description": "Members of a complete dimension sum to the undimensioned total (revenue by service line, segment, site).", "severity": "warn", "concepts": ["fin.pl.revenue", "fin.pl.cost_of_sales", "fin.pl.gross_profit", "kpi.customers_active", "kpi.arr"], "dims": ["service_line", "segment", "site", "customer_type"], "abs_tol": 1.0, "rel_tol": 0.005}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-PER-01', 'period_sum', 'block', 'Fiscal-year, quarter and YTD flows equal the sum of their months.', '{"id": "R-PER-01", "type": "period_sum", "description": "Fiscal-year, quarter and YTD flows equal the sum of their months.", "severity": "block", "concepts": "all duration concepts with aggregation=sum", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-PER-02', 'period_label', 'block', 'A duration fact with months_covered < 12 can never carry period_type FY.', '{"id": "R-PER-02", "type": "period_label", "description": "A duration fact with months_covered < 12 can never carry period_type FY.", "severity": "block"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-PER-03', 'period_label', 'warn', 'Instant facts are dated at a period end (month-end unless the source states a date).', '{"id": "R-PER-03", "type": "period_label", "description": "Instant facts are dated at a period end (month-end unless the source states a date).", "severity": "warn"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-PER-04', 'basis_window', 'block', 'ACTUAL facts end on or before the latest actual month; plan-basis facts may not sit in history views.', '{"id": "R-PER-04", "type": "basis_window", "description": "ACTUAL facts end on or before the latest actual month; plan-basis facts may not sit in history views.", "severity": "block"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-SRC-01', 'source_subtotal', 'block', 'A source subtotal written as a SUM over a row range equals the sum of the extracted lines in that range, and every line in the range is mapped (nothing dropped).', '{"id": "R-SRC-01", "type": "source_subtotal", "description": "A source subtotal written as a SUM over a row range equals the sum of the extracted lines in that range, and every line in the range is mapped (nothing dropped).", "severity": "block", "applies_to": "row_kind=SUM", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-SRC-02', 'source_comparative', 'warn', 'Each subtotal or ratio derived in code equals the source''s own figure for the same concept, period and view. A difference is explained by composition (the source range holds concepts outside the canonical subtotal) or flagged.', '{"id": "R-SRC-02", "type": "source_comparative", "description": "Each subtotal or ratio derived in code equals the source''s own figure for the same concept, period and view. A difference is explained by composition (the source range holds concepts outside the canonical subtotal) or flagged.", "severity": "warn", "applies_to": "status=COMPARATIVE and reason_code in (SOURCE_SUBTOTAL, COMPUTED_IN_CODE)", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-SRC-03', 'annual_column', 'warn', 'A source annual column equals the FY or YTD derived from the months it covers. Its period type comes from the months covered, never from the column header.', '{"id": "R-SRC-03", "type": "annual_column", "description": "A source annual column equals the FY or YTD derived from the months it covers. Its period type comes from the months covered, never from the column header.", "severity": "warn", "applies_to": "row_kind=ANNUAL_COLUMN", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-SUM-ALL', 'summation', 'block', 'Every subtotal equals the weighted sum of its child concepts when all children (or an unclassified residual) are present.', '{"id": "R-SUM-ALL", "type": "summation", "description": "Every subtotal equals the weighted sum of its child concepts when all children (or an unclassified residual) are present.", "severity": "block", "source": "concept.parent links", "abs_tol": 1.0, "rel_tol": 0.001}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-KPI-01', 'identity', 'warn', 'ARR equals MRR times 12 at the same date.', '{"id": "R-KPI-01", "type": "identity", "description": "ARR equals MRR times 12 at the same date.", "severity": "warn", "lhs": "kpi.arr", "rhs": "12*kpi.mrr", "when": "all_present", "abs_tol": 1.0, "rel_tol": 0.005}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-KPI-02', 'identity', 'warn', 'Logo churn equals one minus logo retention.', '{"id": "R-KPI-02", "type": "identity", "description": "Logo churn equals one minus logo retention.", "severity": "warn", "lhs": "kpi.logo_churn_pct", "rhs": "1 - kpi.logo_retention_pct", "when": "all_present", "abs_tol": 0.0005, "rel_tol": 0.0}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-KPI-03', 'inequality', 'warn', 'Gross revenue retention never exceeds net revenue retention or 100%.', '{"id": "R-KPI-03", "type": "inequality", "description": "Gross revenue retention never exceeds net revenue retention or 100%.", "severity": "warn", "expr": ["kpi.grr_pct <= kpi.nrr_pct", "kpi.grr_pct <= 1"]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-KPI-04', 'inequality', 'warn', 'Top-N concentration is between 0 and 100% and rises with N.', '{"id": "R-KPI-04", "type": "inequality", "description": "Top-N concentration is between 0 and 100% and rises with N.", "severity": "warn", "expr": ["0 <= kpi.concentration_top_n_pct <= 1", "monotone_increasing(kpi.concentration_top_n_pct, top_n)"]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-KPI-05', 'roll_forward', 'warn', 'Customer count rolls forward with new and churned customers (allowing reactivations as a stated residual).', '{"id": "R-KPI-05", "type": "roll_forward", "description": "Customer count rolls forward with new and churned customers (allowing reactivations as a stated residual).", "severity": "warn", "opening": "kpi.customers_active@t-1", "flows": ["+kpi.customers_new", "-kpi.customers_churned"], "closing": "kpi.customers_active@t", "abs_tol": 0, "rel_tol": 0.02}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-MKT-01', 'inequality', 'block', 'TAM is at least SAM, and SAM is at least SOM, for the same scope, segment, geography and year.', '{"id": "R-MKT-01", "type": "inequality", "description": "TAM is at least SAM, and SAM is at least SOM, for the same scope, segment, geography and year.", "severity": "block", "expr": ["mkt.tam >= mkt.sam", "mkt.sam >= mkt.som"]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-MKT-02', 'inequality', 'warn', 'SOM is at least the company''s own revenue for the same segment, geography and year; otherwise flag the definition.', '{"id": "R-MKT-02", "type": "inequality", "description": "SOM is at least the company''s own revenue for the same segment, geography and year; otherwise flag the definition.", "severity": "warn", "expr": ["mkt.som >= fin.pl.revenue"]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'R-MKT-03', 'identity', 'warn', 'A bottom-up market equals volume driver times price driver times participation (as recorded in market_build_step).', '{"id": "R-MKT-03", "type": "identity", "description": "A bottom-up market equals volume driver times price driver times participation (as recorded in market_build_step).", "severity": "warn", "lhs": "mkt.tam", "rhs": "mkt.volume_driver * mkt.price_driver", "when": "build=bottom_up", "abs_tol": 1.0, "rel_tol": 0.01}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'P-01', 'range', 'flag', 'Percentages lie within the plausible range for their concept.', '{"id": "P-01", "type": "range", "description": "Percentages lie within the plausible range for their concept.", "severity": "flag", "selector": "unit_type=PERCENT", "min": -1.0, "max": 1.0}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'P-02', 'range', 'flag', 'Retention, NRR and growth may exceed 100% but stay below 500%.', '{"id": "P-02", "type": "range", "description": "Retention, NRR and growth may exceed 100% but stay below 500%.", "severity": "flag", "selector": "concept in (kpi.nrr_pct, drv.revenue_growth_pct, mkt.growth_rate_pct)", "min": -1.0, "max": 5.0}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'P-03', 'range', 'flag', 'Counts are non-negative.', '{"id": "P-03", "type": "range", "description": "Counts are non-negative.", "severity": "flag", "selector": "unit_type=COUNT", "min": 0, "max": null}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'P-04', 'range', 'flag', 'Days lie between 0 and 730.', '{"id": "P-04", "type": "range", "description": "Days lie between 0 and 730.", "severity": "flag", "selector": "unit_type=DAYS", "min": 0, "max": 730}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'P-05', 'range', 'flag', 'Currency facts lie within 0.001x to 1,000x of the company''s revenue scale.', '{"id": "P-05", "type": "range", "description": "Currency facts lie within 0.001x to 1,000x of the company''s revenue scale.", "severity": "flag", "selector": "unit_type=CURRENCY", "min": "0.001*revenue_scale", "max": "1000*revenue_scale"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_rule VALUES ('1.0.0', 'P-06', 'range', 'flag', 'Margins lie between -100% and 100%.', '{"id": "P-06", "type": "range", "description": "Margins lie between -100% and 100%.", "severity": "flag", "selector": "concept in (drv.gross_margin_pct, drv.ebitda_margin_pct)", "min": -1.0, "max": 1.0}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO onto_reason_code VALUES ('1.0.0', 'EQUAL_AUTHORITY_CONFLICT', 'Two sources of equal authority disagree beyond tolerance') ON CONFLICT DO NOTHING;
INSERT INTO onto_reason_code VALUES ('1.0.0', 'VALIDATION_FAILED', 'A calculation or identity rule failed; rule id in reason_detail') ON CONFLICT DO NOTHING;
INSERT INTO onto_reason_code VALUES ('1.0.0', 'NO_PERIOD', 'Period could not be determined') ON CONFLICT DO NOTHING;
INSERT INTO onto_reason_code VALUES ('1.0.0', 'PERIOD_CONFLICT', 'Label period and header period disagree') ON CONFLICT DO NOTHING;
INSERT INTO onto_reason_code VALUES ('1.0.0', 'NO_UNIT', 'Unit or scale could not be determined') ON CONFLICT DO NOTHING;
INSERT INTO onto_reason_code VALUES ('1.0.0', 'IMPLAUSIBLE_VALUE', 'Plausibility rule failed') ON CONFLICT DO NOTHING;
INSERT INTO onto_reason_code VALUES ('1.0.0', 'PARENT_UNKNOWN', 'Line could not be placed under any parent node') ON CONFLICT DO NOTHING;
INSERT INTO onto_reason_code VALUES ('1.0.0', 'OUT_OF_SCOPE', 'Document type routed to another module') ON CONFLICT DO NOTHING;
INSERT INTO onto_reason_code VALUES ('1.0.0', 'SUPERSEDED_VERSION', 'A newer version of the document exists') ON CONFLICT DO NOTHING;
INSERT INTO onto_reason_code VALUES ('1.0.0', 'NOT_IN_DATA_ROOM', 'Document is not part of the deal''s data room') ON CONFLICT DO NOTHING;
INSERT INTO onto_reason_code VALUES ('1.0.0', 'FORMULA_ERROR', 'Source cell holds a spreadsheet error value (a broken reference or a failed lookup)') ON CONFLICT DO NOTHING;
INSERT INTO onto_reason_code VALUES ('1.0.0', 'MISSING_VALUE', 'The source shows text or nothing where a value should be (for example ''needs data'')') ON CONFLICT DO NOTHING;
INSERT INTO onto_reason_code VALUES ('1.0.0', 'LABEL_VALUE', 'Value was found inside a label (ID, code, account number)') ON CONFLICT DO NOTHING;
INSERT INTO onto_reason_code VALUES ('1.0.0', 'DUPLICATE', 'Merged into an existing fact with the same key') ON CONFLICT DO NOTHING;
INSERT INTO onto_reason_code VALUES ('1.0.0', 'LOWER_AUTHORITY', 'Kept as comparative; a higher-authority source was selected') ON CONFLICT DO NOTHING;
INSERT INTO onto_reason_code VALUES ('1.0.0', 'USER_EXCLUDED', 'Excluded by a reviewer, reason recorded') ON CONFLICT DO NOTHING;
INSERT INTO onto_reason_code VALUES ('1.0.0', 'BASIS_MISMATCH', 'Plan and actual cannot be compared') ON CONFLICT DO NOTHING;
INSERT INTO onto_reason_code VALUES ('1.0.0', 'SOURCE_SUBTOTAL', 'Source subtotal kept as a check; the canonical subtotal is derived from lines in code') ON CONFLICT DO NOTHING;
INSERT INTO onto_reason_code VALUES ('1.0.0', 'COMPUTED_IN_CODE', 'Ratio or derived metric recomputed by the calculation engine; the source value is kept as a check') ON CONFLICT DO NOTHING;
INSERT INTO onto_record_class VALUES ('1.0.0', 'document', ARRAY['doc_id','file_name','path','format','doc_type','version_group','version_rank','is_primary','in_data_room','basis_default','evidence_tier','period_end','status (READ|PARTIAL|SKIPPED|FAILED)','status_reason','pages_or_sheets','facts_count','hash']::text[]) ON CONFLICT DO NOTHING;
INSERT INTO onto_record_class VALUES ('1.0.0', 'source_location', ARRAY['doc_id','sheet_or_page','table_id','cell_range_or_bbox','row_label_as_read','column_label_as_read','value_as_read','extraction_method','transform_steps']::text[]) ON CONFLICT DO NOTHING;
INSERT INTO onto_record_class VALUES ('1.0.0', 'scope_basis', ARRAY['period_or_item','doc_id','basis','tier','materiality']::text[]) ON CONFLICT DO NOTHING;
INSERT INTO onto_record_class VALUES ('1.0.0', 'facility', ARRAY['facility_id','lender','debt_class','description','currency','original_amount','start_date','maturity_date','term_months','rate_type','interest_rate','payment','security','covenants','gl_account','status']::text[]) ON CONFLICT DO NOTHING;
INSERT INTO onto_record_class VALUES ('1.0.0', 'lease', ARRAY['lease_id','site','asset','lessor','start_date','end_date','term_years','base_rent','escalator','renewal_options','security_deposit','guarantor','status (executed|draft|missing)']::text[]) ON CONFLICT DO NOTHING;
INSERT INTO onto_record_class VALUES ('1.0.0', 'adjustment', ARRAY['ref (ADJ-nn / PF-nn)','title','category (definitional|normalisation|non_recurring|out_of_period|run_rate|pro_forma|reclassification)','from_view','to_view','nature_and_evidence','treatment (accepted|rejected|considered_nil|open)','tier','proposed_by (management|adviser|diligence)','linked_facts']::text[]) ON CONFLICT DO NOTHING;
INSERT INTO onto_record_class VALUES ('1.0.0', 'sensitivity', ARRAY['ref (S-nn)','title','direction','rationale','linked_adjustment']::text[]) ON CONFLICT DO NOTHING;
INSERT INTO onto_record_class VALUES ('1.0.0', 'debt_like_item', ARRAY['item_id','debt_like_type','description','as_at','amount','status (proposed|agreed|rejected)','rationale','doc_id']::text[]) ON CONFLICT DO NOTHING;
INSERT INTO onto_record_class VALUES ('1.0.0', 'customer', ARRAY['customer_id','segment','first_period','status','contract_id']::text[]) ON CONFLICT DO NOTHING;
INSERT INTO onto_record_class VALUES ('1.0.0', 'contract', ARRAY['contract_id','counterparty','type','start_date','end_date','term','renewal','price_terms','escalator','termination_rights','exclusivity','in_data_room']::text[]) ON CONFLICT DO NOTHING;
INSERT INTO onto_record_class VALUES ('1.0.0', 'competitor', ARRAY['competitor_id','name','archetype','footprint','segments','capabilities','processing_or_assets','threat_level','source']::text[]) ON CONFLICT DO NOTHING;
INSERT INTO onto_record_class VALUES ('1.0.0', 'market_definition', ARRAY['market_id','segment','definition','geography','included','excluded','scope (CURRENT|EXPANDED)']::text[]) ON CONFLICT DO NOTHING;
INSERT INTO onto_record_class VALUES ('1.0.0', 'market_build_step', ARRAY['market_id','step','driver','value','unit','source','grade']::text[]) ON CONFLICT DO NOTHING;
